mapper.update:
update member
name = #{name}, gender = #{gender}, password = #{password}, age = #{age}, image = #{image}, self_intro = #{selfIntro}, number = #{number}, pos = #{pos}
where id = #{id}

mapper.select:
select id,username,password,name,image,group_id
from member
where username = #{username}

select m.id, m.username, m.name, m.group_id, g.name as group_name,
       m.gender, m.age, m.image, m.self_intro, m.number, m.pos
from member m
left join `group` g on m.group_id = g.id


        and m.name like concat('%', #{query.name}, '%')


        and m.gender = #{query.gender}


        and m.pos = #{query.pos}


        and g.name like concat('%', #{query.groupName}, '%')


order by m.id desc
limit #{query.pageSize} offset #{offset}

select count(*) from member m left join `group` g on m.group_id = g.id
and m.name like concat('%', #{query.name}, '%')
and m.gender = #{query.gender}
and m.pos = #{query.pos}
and g.name like concat('%', #{query.groupName}, '%')

